
/*Create tables*/

create table public.products (
  product_id integer generated by default as identity not null,
  title character varying(255) not null,
  category character varying(255) not null,
  price numeric(10, 2) not null,
  newprice numeric(10, 2) not null,
  rating numeric(10, 2) not null,
  description character varying(255) null,
  images character varying(255) not null,
  reviews jsonb null default '[]'::jsonb,
  amount integer null,
  constraint products_pkey primary key (product_id)
) TABLESPACE pg_default;

create index IF not exists idx_product_reviews on public.products using btree (reviews) TABLESPACE pg_default;


create table public.cart (
  cart_id serial not null,
  user_id character varying(50) null,
  product_id integer null,
  quantity integer not null default 1,
  created_at timestamp without time zone null default CURRENT_TIMESTAMP,
  constraint cart_pkey primary key (cart_id),
  constraint cart_product_id_fkey foreign KEY (product_id) references products (product_id) on delete CASCADE,
  constraint cart_user_id_fkey foreign KEY (user_id) references users (user_id) on delete CASCADE
) TABLESPACE pg_default;

create index IF not exists idx_cart_user_product on public.cart using btree (user_id, product_id) TABLESPACE pg_default;


create table public.users (
  user_id character varying(50) not null,
  username character varying(50) not null,
  password character varying(100) not null,
  is_dark boolean null default false,
  role character varying(50) null default 'Client'::character varying,
  constraint users_pkey primary key (user_id),
  constraint unique_name unique (username)
) TABLESPACE pg_default;



create table public.refresh_table (
  id serial not null,
  user_id character varying(50) not null,
  token text not null,
  expired_at timestamp with time zone not null,
  constraint refreshtable_pkey primary key (id),
  constraint foreign_user_id foreign KEY (user_id) references users (user_id) on delete CASCADE
) TABLESPACE pg_default;

create index IF not exists user_id_index on public.refresh_table using btree (user_id) TABLESPACE pg_default;

create index IF not exists token_index on public.refresh_table using btree (token) TABLESPACE pg_default;


